  const closeBtn = document.getElementById('dialog-close-btn');

  // Track the element that opened the dialog so we can restore focus on close
  let openerEl = null;

  function openDialog() {
    openerEl = document.activeElement;
    dialog.showModal();
    // Move focus to the safe "Cancel" button (destructive action default)
    cancelBtn.focus();
  }

  function closeDialog() {
    dialog.close();
    if (openerEl) openerEl.focus();
  }

  trigger.addEventListener('click', openDialog);
  cancelBtn.addEventListener('click', closeDialog);
  closeBtn.addEventListener('click', closeDialog);

  confirmBtn.addEventListener('click', () => {
    // In a real app, fire the delete request here.
    closeDialog();
    // Provide a brief live-region confirmation to assistive technologies
    const notice = document.getElementById('action-notice');
    notice.textContent = 'Image deleted from your library.';
    setTimeout(() => { notice.textContent = ''; }, 4000);
  });

  // Close on backdrop click
  dialog.addEventListener('click', (e) => {
    const rect = dialog.getBoundingClientRect();
    const isBackdrop =
