const js   = fs.readFileSync('script.js','utf8');

// Basic checks
const checks = [
  ['dialog element present',      /<dialog/i.test(html)],
  ['dialog closed by default',    !/<dialog[^>]+open/i.test(html)],
  ['trigger class on button',     /class=\"[^\"]*trigger/.test(html)],
