  ['Escape handled',              /cancel/.test(js)],
  ['skip link present',           /skip-link/.test(html)],
  ['live region present',         /role=\"status\"/.test(html)],
  ['showModal called',            /showModal/.test(js)],
];

let pass = true;
checks.forEach(([name, ok]) => {
  console.log((ok ? '✓' : '✗') + ' ' + name);
  if (!ok) pass = false;
});
